const materialCard=({component,snapshot,getComponentName,getComponentDetails})=>{
 const catalogItem=componentCatalogEntry(snapshot,component),details=getComponentDetails(component.materialId);
 const name=escapeHtml(displayName(details?.name||getComponentName(component.materialId))||component.materialId),imageUrl=details?.image||catalogItem?.image;
 const image=imageUrl?'<img src="'+escapeHtml(imageUrl)+'" alt="" loading="lazy" decoding="async">':'';
 const keyword=MATERIAL_KEYWORDS[component.materialId]||'';
 const cardVariant = component.componentType === 'stone' ? 'lucky-card-stone' : 'lucky-card-talisman';
 return '<article class="lumi-material-card '+cardVariant+'" data-material-id="'+escapeHtml(component.materialId)+'" data-material-type="'+(component.componentType === 'stone' ? 'stone' : 'talisman')+'">'+image+'<div><h3>'+name+'</h3>'+(keyword?'<p>'+escapeHtml(keyword)+'</p>':'')+'</div></article>';
};
const recommendationContextCopy = ({ answers, selected, getComponentName }) => {
  const weekday = WEEKDAYS.find(([id]) => id === answers.weekday)?.[1];
  const dateParts = [answers.birthDate, answers.birthMonth ? THAI_MONTHS[Number(answers.birthMonth) - 1] : '', answers.birthYear].filter(Boolean);
  const person = weekday ? `ผู้เกิดวัน${weekday}${dateParts.length ? ` ที่ ${dateParts.join(' ')}` : ''}` : (dateParts.length ? `ผู้เกิดวันที่ ${dateParts.join(' ')}` : 'คุณ');
  const goals = answers.goals.map((id) => goalLabels[id]).filter(Boolean);
  const names = uniqueByMaterial(selected.sequence.filter((component) => component.componentType === 'stone')).map((component) => displayName(getComponentName(component.materialId))).filter(Boolean);
  const styleLine = answers.style === 'charm' ? 'โดยมีเครื่องรางเป็นศูนย์กลางของกำไล' : 'เน้นหินล้วนให้สวยและใส่ได้ทุกวัน';
  return { person, goals, materialLine: names.length ? `น้อง Lucky เลือกหิน ${names.join(' · ')} มาให้สอดคล้องกับสิ่งที่คุณเลือก ตามความหมายของหินในคอลเลกชัน` : 'น้อง Lucky เลือกวัสดุมาให้สอดคล้องกับสิ่งที่คุณเลือก ตามข้อมูลในคอลเลกชัน', styleLine };
};

